+const PROP_ALIGNMENT = 0x0002;
+const PROP_BACKGROUND_COLOR = 0x1001;
+const PROP_FONT_SIZE = 0x1007;
+const PROP_FONT_WEIGHT = 0x1008;
+const PROP_COLOR = 0x100a;
+const PROP_WIDTH = 0x100b;
+const PROP_HEIGHT = 0x100c;
+const PROP_OPACITY = 0x100d;
+const PROP_VISIBLE = 0x100e;
+const PROP_PADDING = 0x1011;
+const PROP_PADDING_TOP = 0x1012;
+const PROP_PADDING_RIGHT = 0x1013;
+const PROP_PADDING_BOTTOM = 0x1014;
+const PROP_PADDING_LEFT = 0x1015;

+const SIZE_FILL = -1;
+
 // Hydrate the server-rendered DOM: node id -> element.
