+
+function applyPadding(nodeId) {
+    const el = byId.get(nodeId);
+    if (!el) return;
+    const p = pads.get(nodeId);
+    const top = p.top ?? p.base;
+    const right = p.right ?? p.base;
+    const bottom = p.bottom ?? p.base;
+    const left = p.left ?? p.base;
+    el.style.paddingTop = top == null ? "" : `${top}px`;
+    el.style.paddingRight = right == null ? "" : `${right}px`;
+    el.style.paddingBottom = bottom == null ? "" : `${bottom}px`;
+    el.style.paddingLeft = left == null ? "" : `${left}px`;
+}
+
 // Read a length-prefixed string (`[u32 len][bytes]`) at a relative offset.
 function readString(strings, offset) {
     const view = new DataView(strings.buffer, strings.byteOffset, strings.byteLength);
     const len = view.getUint32(offset, true);
     const bytes = strings.subarray(offset + 4, offset + 4 + len);
     return new TextDecoder().decode(bytes);
 }

 function applyBatch(bytes) {
     const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
     const opcodeCount = view.getUint32(12, true);
     const opcodesEnd = 16 + opcodeCount * 16;
     const stringsLen = view.getUint32(opcodesEnd, true);
     const stringsStart = opcodesEnd + 4;
     const strings = bytes.subarray(stringsStart, stringsStart + stringsLen);

     for (let i = 0; i < opcodeCount; i++) {
         const pos = 16 + i * 16;
         const category = view.getUint8(pos);
         const command = view.getUint8(pos + 1);
         const a = view.getUint32(pos + 4, true);
         const b = view.getUint32(pos + 8, true);
         const c = view.getUint32(pos + 12, true);
         if (category === CAT_STYLE && command === CMD_SET_TEXT) {
             const el = byId.get(a);
             if (!el) continue;
             const text = readString(strings, b);
             // Text fields carry their value in the input; other controls carry
             // their label in an inner span (textContent would clobber the input).
             const input = el.querySelector("input[type=text]");
             if (input) input.value = text;
             else {
                 const span = el.querySelector(".pathland-text");
                 if (span) span.textContent = text;
                 else el.textContent = text;
             }
         } else if (category === CAT_STYLE && command === CMD_SET_PROPERTY) {
             const propId = b & 0xffff;
             const valueType = (b >>> 16) & 0xff;
             if (valueType === VAL_STRING) {
                 const el = byId.get(a);
                 if (!el) continue;
                 const text = readString(strings, c);
                 if (propId === PROP_LABEL) {
                     const span = el.querySelector(".pathland-label");
                     if (span) span.textContent = text;
                 } else if (propId === PROP_PROMPT) {
                     const input = el.querySelector("input[type=text]");
                     if (input) input.placeholder = text;
                 }
             } else if (propId === PROP_SELECTED) {
                 const el = byId.get(a);
                 if (!el) continue;
                 const input = el.querySelector("input[type=checkbox]");
                 if (input) input.checked = (c & 0xff) !== 0;
             } else if (propId === PROP_VALUE) {
                 const el = byId.get(a);
                 if (!el) continue;
                 const input = el.querySelector("input[type=range]");
                 if (input) input.value = String(f32FromBits(c));
             } else if (propId === PROP_BORDER_COLOR) {
                 const el = byId.get(a);
                 if (!el) continue;
                 const color = argbToRgba(c);
                 el.style.borderTopColor = color;
                 el.style.borderRightColor = color;
                 el.style.borderBottomColor = color;
                 el.style.borderLeftColor = color;
+            } else if (propId === PROP_PADDING || (propId >= PROP_PADDING_TOP && propId <= PROP_PADDING_LEFT)) {
+                const el = byId.get(a);
+                if (!el) continue;
+                let p = pads.get(a);
+                if (!p) { p = {}; pads.set(a, p); }
+                if (propId === PROP_PADDING) p.base = f32FromBits(c);
+                else if (propId === PROP_PADDING_TOP) p.top = f32FromBits(c);
+                else if (propId === PROP_PADDING_RIGHT) p.right = f32FromBits(c);
+                else if (propId === PROP_PADDING_BOTTOM) p.bottom = f32FromBits(c);
+                else p.left = f32FromBits(c);
+                applyPadding(a);
+            } else if (valueType === VAL_COLOR) {
+                const el = byId.get(a);
+                if (!el) continue;
+                const color = argbToRgba(c);
+                if (propId === PROP_COLOR) el.style.color = color;
+                else if (propId === PROP_BACKGROUND_COLOR) el.style.backgroundColor = color;
+            } else if (propId === PROP_FONT_SIZE) {
+                const el = byId.get(a);
+                if (el) el.style.fontSize = f32FromBits(c) + "px";
+            } else if (propId === PROP_FONT_WEIGHT) {
+                const el = byId.get(a);
+                if (el) el.style.fontWeight = cssFontWeight(f32FromBits(c));
+            } else if (propId === PROP_OPACITY) {
+                const el = byId.get(a);
+                if (el) el.style.opacity = String(f32FromBits(c));
+            } else if (propId === PROP_VISIBLE) {
+                const el = byId.get(a);
+                if (el) el.style.display = f32FromBits(c) === 0 ? "none" : "";
+            } else if (propId === PROP_WIDTH) {
+                const el = byId.get(a);
+                if (!el) continue;
+                const width = f32FromBits(c);
+                if (width === SIZE_FILL) el.style.flexGrow = "1";
+                else if (width > 0) el.style.width = width + "px";
+            } else if (propId === PROP_HEIGHT) {
+                const el = byId.get(a);
+                if (!el) continue;
+                const height = f32FromBits(c);
+                if (height === SIZE_FILL) el.style.alignSelf = "stretch";
+                else if (height > 0) el.style.height = height + "px";
+            } else if (propId === PROP_ALIGNMENT) {
+                const el = byId.get(a);
+                if (el) el.style.alignSelf = cssAlignment(f32FromBits(c));
