private String wrapStack(int id, String direction, Node node, String children, String style) {
    StringBuilder css = new StringBuilder("display:flex;flex-direction:").append(direction).append(';');
    Float spacing = node.spacing();
    if (spacing != null) {
        css.append("gap:").append(fmt(spacing)).append("px;");
    }
    Integer alignment = node.color(Properties.ALIGNMENT);
    css.append("align-items:").append(alignment == null ? "center" : cssAlignment(alignment)).append(';');
    css.append(style);
    return "<div data-pathland-id=\"" + id + "\" style=\"" + css + "\">" + children + "</div>";
