input.newString:
// Format a packed 0xAARRGGBB color as an `rgba(...)` string.
function argbToRgba(bits) {
    const a = (bits >>> 24) & 0xff;
    const r = (bits >>> 16) & 0xff;
    const g = (bits >>> 8) & 0xff;
    const b = bits & 0xff;
    return `rgba(${r},${g},${b},${(a / 255).toFixed(3)})`;
}

// Map a protocol FontWeight wire value to CSS font-weight.
function cssFontWeight(wire) {
    switch (wire) {
        case 0: return "300";  // LIGHT
        case 2: return "500";  // MEDIUM
        case 3: return "600";  // SEMIBOLD
        case 4: return "bold"; // BOLD
        default: return "normal"; // REGULAR
    }
}

// Map a protocol Alignment wire value to a CSS flex keyword.
function cssAlignment(wire) {
    switch (wire) {
        case 0: return "flex-start"; // LEADING
        case 2: return "flex-end";   // TRAILING
        case 3: return "stretch";    // FILL
        default: return "center";    // CENTER
    }
}

