/**
 * Pathland wire-protocol constants — the TypeScript mirror of
 * `pathland_core::constants` (see `lib/rust/crates/pathland-core/src/constants.rs`
 * and `spec/OPCODE.md`). These IDs are part of the wire format and must not change.
 */
export const CATEGORY = {
  TREE: 0x01,
  STYLE: 0x02,
  EVENT: 0x03,
  META: 0x04,
} as const;

export const TREE = {
  CREATE_NODE: 0x01,
  DELETE_NODE: 0x02,
  INSERT_CHILD: 0x03,
  REMOVE_CHILD: 0x04,
  MOVE_CHILD: 0x05,
} as const;

export const STYLE = {
  SET_PROPERTY: 0x01,
  SET_DESIGN_TOKEN: 0x02,
  SET_TEXT: 0x03,
} as const;

export const EVENT = {
  POINTER_DOWN: 0x01,
  POINTER_MOVE: 0x02,
  POINTER_UP: 0x03,
  KEY_DOWN: 0x04,
  KEY_UP: 0x05,
  VALUE_CHANGED: 0x06,
  TEXT_CHANGED: 0x07,
} as const;

export const VALUE_TYPE = {
  U8: 0x01,
  U32: 0x02,
  I32: 0x03,
  F32: 0x04,
  STRING: 0x05,
  ENUM: 0x06,
  COLOR: 0x07,
  DESIGN_TOKEN: 0x08,
} as const;

/** Component types (`u16`, low half of `B` in `TREE::CREATE_NODE`). */
export const COMPONENT = {
  HSTACK: 0x0001,
  VSTACK: 0x0002,
  TEXT: 0x0003,
  BUTTON: 0x0004,
  IMAGE: 0x0005,
  SWITCH: 0x0006,
  TEXT_FIELD: 0x0007,
  SPACER: 0x0008,
  SCROLLVIEW: 0x0009,
  LIST: 0x000a,
  GRID: 0x000b,
  COMMENT: 0x000c,
  CHECKBOX: 0x000d,
  SLIDER: 0x000e,
} as const;

/** Property ids (`u16`, low half of `B` in `STYLE::SET_PROPERTY`). */
export const PROPERTY = {
  SPACING: 0x0001,
  ALIGNMENT: 0x0002,
  CONTENT_MARGINS: 0x0005,
  TEXT: 0x000a,
  LINE_LIMIT: 0x000b,
  TEXT_ALIGNMENT: 0x000c,
  TRUNCATION_MODE: 0x000d,
  BACKGROUND_COLOR: 0x1001,
  BORDER_WIDTH: 0x1003,
  BORDER_COLOR: 0x1004,
  BORDER_RADIUS: 0x1005,
  PADDING_STYLE: 0x1006,
  FONT_SIZE: 0x1007,
  FONT_WEIGHT: 0x1008,
  FONT_FAMILY: 0x1009,
  COLOR: 0x100a,
  WIDTH: 0x100b,
  HEIGHT: 0x100c,
  OPACITY: 0x100d,
  VISIBLE: 0x100e,
  Z_INDEX: 0x100f,
  CLIPS_TO_BOUNDS: 0x1010,
  PADDING: 0x1011,
  PADDING_TOP: 0x1012,
  PADDING_RIGHT: 0x1013,
  PADDING_BOTTOM: 0x1014,
  PADDING_LEFT: 0x1015,
  BORDER_EDGES: 0x1016,
  ROLE: 0x2001,
  STATE: 0x2002,
  ENABLED: 0x2003,
  SELECTED: 0x2004,
  EVENT_LISTENERS: 0x2005,
  VALUE: 0x2006,
  MIN_VALUE: 0x2007,
  MAX_VALUE: 0x2008,
  LABEL: 0x200a,
  PROMPT: 0x200b,
} as const;

/** `EVENT_LISTENERS` bitmask bits. */
export const LISTENER = {
  POINTER_DOWN: 1 << 0,
  POINTER_MOVE: 1 << 1,
  POINTER_UP: 1 << 2,
  KEY_DOWN: 1 << 3,
  KEY_UP: 1 << 4,
} as const;

/** `BORDER_EDGES` bitmask bits. */
export const BORDER_EDGE = {
  TOP: 1 << 0,
  LEADING: 1 << 1,
  BOTTOM: 1 << 2,
  TRAILING: 1 << 3,
  ALL: 0x0f,
} as const;

/** Special `WIDTH`/`HEIGHT` size constants. */
export const SIZE = {
  FILL: -1.0,
  HUG_CONTENT: -2.0,
} as const;

/** `Alignment` wire values (protocol ENUM). */
export const ALIGNMENT = {
  LEADING: 0,
  CENTER: 1,
  TRAILING: 2,
  FILL: 3,
} as const;

/** `FontWeight` wire values (protocol ENUM). */
export const FONT_WEIGHT = {
  LIGHT: 0,
  REGULAR: 1,
  MEDIUM: 2,
  SEMIBOLD: 3,
  BOLD: 4,
} as const;

import { Opcode, Frame } from './frame';

/**
 * The `PLPL` network batch codec — the TypeScript mirror of the Java
 * `com.pathland.view.transport.FrameCodec` and the Rust `pathland_core_transport`.
 *
 * Batch wire format (both directions share the header):
 *
 * ```
 * magic "PLPL" (u32 LE) | version (u16) | flags (u16) | frameCount (u32)
 * | opcodeCount (u32) | opcodes (16 B × count) | stringsLen (u32) | string bytes
 * ```
 *
 * Frames are self-contained: `SET_TEXT` / STRING-valued `SET_PROPERTY` reference
 * entries in the batch's own string section by *relative* offset.
 */
export const BATCH_MAGIC = 0x504c_504c; // "PLPL"
export const BATCH_VERSION = 1;
export const HOST_TO_GUEST = 0x0001;
export const HEADER_BYTES = 16;

const encoder = new TextEncoder();
const decoder = new TextDecoder();

/** Decode a `PLPL` batch into a frame (opcodes + string section). */
export function decodeFrame(bytes: Uint8Array): Frame {
  if (bytes.byteLength < HEADER_BYTES) {
    throw new Error('batch truncated');
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.getUint32(0, true) !== BATCH_MAGIC) {
    throw new Error('bad batch magic');
  }
  if (view.getUint16(4, true) !== BATCH_VERSION) {
    throw new Error('unsupported batch version');
  }
  const opcodeCount = view.getUint32(12, true);
  const opcodesEnd = HEADER_BYTES + opcodeCount * 16;
  if (opcodesEnd + 4 > bytes.byteLength) {
    throw new Error('batch truncated (opcodes)');
  }
  const opcodes: Opcode[] = new Array(opcodeCount);
  for (let i = 0; i < opcodeCount; i++) {
    const pos = HEADER_BYTES + i * 16;
    opcodes[i] = new Opcode(
      view.getUint8(pos),
      view.getUint8(pos + 1),
      view.getUint16(pos + 2, true),
      view.getUint32(pos + 4, true),
      view.getUint32(pos + 8, true),
      view.getUint32(pos + 12, true),
    );
  }
  const stringsLen = view.getUint32(opcodesEnd, true);
  const stringsStart = opcodesEnd + 4;
  if (stringsStart + stringsLen > bytes.byteLength) {
    throw new Error('batch truncated (strings)');
  }
  const strings = bytes.subarray(stringsStart, stringsStart + stringsLen);
  return new Frame(opcodes, strings);
}

/** Read a length-prefixed string (`[u32 len][bytes]`) at a relative offset. */
export function stringAt(strings: Uint8Array, offset: number): string {
  const view = new DataView(strings.buffer, strings.byteOffset, strings.byteLength);
  const len = view.getUint32(offset, true);
  return decoder.decode(strings.subarray(offset + 4, offset + 4 + len));
}

/**
 * Encode a frame (or host→guest event batch) as a `PLPL` byte array.
 * `flags` selects the direction (`HOST_TO_GUEST` for events).
 */
export function encodeBatch(
  opcodes: Opcode[],
  strings: Uint8Array,
  flags = 0,
): Uint8Array {
  const opcodesEnd = HEADER_BYTES + opcodes.length * 16;
  const out = new Uint8Array(opcodesEnd + 4 + strings.byteLength);
  const view = new DataView(out.buffer);
  view.setUint32(0, BATCH_MAGIC, true);
  view.setUint16(4, BATCH_VERSION, true);
  view.setUint16(6, flags, true);
  view.setUint32(8, 0, true); // frameCount
  view.setUint32(12, opcodes.length, true);
  for (let i = 0; i < opcodes.length; i++) {
    const pos = HEADER_BYTES + i * 16;
    const op = opcodes[i];
    view.setUint8(pos, op.category);
    view.setUint8(pos + 1, op.command);
    view.setUint16(pos + 2, op.flags, true);
    view.setUint32(pos + 4, op.a, true);
    view.setUint32(pos + 8, op.b, true);
    view.setUint32(pos + 12, op.c, true);
  }
  view.setUint32(opcodesEnd, strings.byteLength, true);
  out.set(strings, opcodesEnd + 4);
  return out;
}

/** Append a length-prefixed string to an encoder buffer. */
export function writeString(buffer: number[]): (text: string) => number {
  const bytes: number[] = [];
  const start = buffer.length;
  const push = (b: number) => {
    bytes.push(b);
    buffer.push(b);
  };
  return (text: string) => {
    const utf8 = encoder.encode(text);
    push((utf8.length >>> 0) & 0xff);
    push((utf8.length >>> 8) & 0xff);
    push((utf8.length >>> 16) & 0xff);
    push((utf8.length >>> 24) & 0xff);
    for (const b of utf8) {
      push(b);
    }
    void start;
    return start;
  };
}

import { stringAt } from './decoder';

/**
 * A fixed-size 16-byte Pathland opcode (the wire format, little-endian):
 *
 * ```
 * [Category u8][Command u8][Flags u16][A u32][B u32][C u32]
 * ```
 *
 * Matches `pathland_core::Opcode` and `spec/OPCODE.md`.
 */
export class Opcode {
  constructor(
    readonly category: number,
    readonly command: number,
    readonly flags: number,
    readonly a: number,
    readonly b: number,
    readonly c: number,
  ) {}

  /** The `propertyId` carried in the low half of `B` of a `SET_PROPERTY`. */
  propertyId(): number {
    return this.b & 0xffff;
  }

  /** The `valueType` carried in the high byte of `B` of a `SET_PROPERTY`. */
  valueType(): number {
    return (this.b >>> 16) & 0xff;
  }
}

/** A self-contained frame: opcodes + the batch's own string section. */
export class Frame {
  constructor(
    readonly opcodes: Opcode[],
    readonly strings: Uint8Array,
  ) {}

  /** Resolve a relative string offset in this frame's string section. */
  stringAt(offset: number): string {
    return stringAt(this.strings, offset);
  }
}

import { Opcode, Frame } from './frame';

/**
 * The `PLPL` network batch codec — the TypeScript mirror of the Java
 * `com.pathland.view.transport.FrameCodec` and the Rust `pathland_core_transport`.
 *
 * Batch wire format (both directions share the header):
 *
 * ```
 * magic "PLPL" (u32 LE) | version (u16) | flags (u16) | frameCount (u32)
 * | opcodeCount (u32) | opcodes (16 B × count) | stringsLen (u32) | string bytes
 * ```
 *
 * Frames are self-contained: `SET_TEXT` / STRING-valued `SET_PROPERTY` reference
 * entries in the batch's own string section by *relative* offset.
 */
export const BATCH_MAGIC = 0x504c_504c; // "PLPL"
export const BATCH_VERSION = 1;
export const HOST_TO_GUEST = 0x0001;
export const HEADER_BYTES = 16;

const encoder = new TextEncoder();
const decoder = new TextDecoder();

/** Decode a `PLPL` batch into a frame (opcodes + string section). */
export function decodeFrame(bytes: Uint8Array): Frame {
  if (bytes.byteLength < HEADER_BYTES) {
    throw new Error('batch truncated');
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.getUint32(0, true) !== BATCH_MAGIC) {
    throw new Error('bad batch magic');
  }
  if (view.getUint16(4, true) !== BATCH_VERSION) {
    throw new Error('unsupported batch version');
  }
  const opcodeCount = view.getUint32(12, true);
  const opcodesEnd = HEADER_BYTES + opcodeCount * 16;
  if (opcodesEnd + 4 > bytes.byteLength) {
    throw new Error('batch truncated (opcodes)');
  }
  const opcodes: Opcode[] = new Array(opcodeCount);
  for (let i = 0; i < opcodeCount; i++) {
    const pos = HEADER_BYTES + i * 16;
    opcodes[i] = new Opcode(
      view.getUint8(pos),
      view.getUint8(pos + 1),
      view.getUint16(pos + 2, true),
      view.getUint32(pos + 4, true),
      view.getUint32(pos + 8, true),
      view.getUint32(pos + 12, true),
    );
  }
  const stringsLen = view.getUint32(opcodesEnd, true);
  const stringsStart = opcodesEnd + 4;
  if (stringsStart + stringsLen > bytes.byteLength) {
    throw new Error('batch truncated (strings)');
  }
  const strings = bytes.subarray(stringsStart, stringsStart + stringsLen);
  return new Frame(opcodes, strings);
}

/** Read a length-prefixed string (`[u32 len][bytes]`) at a relative offset. */
export function stringAt(strings: Uint8Array, offset: number): string {
  const view = new DataView(strings.buffer, strings.byteOffset, strings.byteLength);
  const len = view.getUint32(offset, true);
  return decoder.decode(strings.subarray(offset + 4, offset + 4 + len));
}

/**
 * Encode a frame (or host→guest event batch) as a `PLPL` byte array.
 * `flags` selects the direction (`HOST_TO_GUEST` for events).
 */
export function encodeBatch(
  opcodes: Opcode[],
  strings: Uint8Array,
  flags = 0,
): Uint8Array {
  const opcodesEnd = HEADER_BYTES + opcodes.length * 16;
  const out = new Uint8Array(opcodesEnd + 4 + strings.byteLength);
  const view = new DataView(out.buffer);
  view.setUint32(0, BATCH_MAGIC, true);
  view.setUint16(4, BATCH_VERSION, true);
  view.setUint16(6, flags, true);
  view.setUint32(8, 0, true); // frameCount
  view.setUint32(12, opcodes.length, true);
  for (let i = 0; i < opcodes.length; i++) {
    const pos = HEADER_BYTES + i * 16;
    const op = opcodes[i];
    view.setUint8(pos, op.category);
    view.setUint8(pos + 1, op.command);
    view.setUint16(pos + 2, op.flags, true);
    view.setUint32(pos + 4, op.a, true);
    view.setUint32(pos + 8, op.b, true);
    view.setUint32(pos + 12, op.c, true);
  }
  view.setUint32(opcodesEnd, strings.byteLength, true);
  out.set(strings, opcodesEnd + 4);
  return out;
}

/** A growable string-section writer returning each entry's relative offset. */
export class StringSectionWriter {
  private readonly bytes: number[] = [];

  /** The byte length of the string section so far. */
  size(): number {
    return this.bytes.length;
  }

  /** Append a length-prefixed UTF-8 string; returns its relative offset. */
  push(text: string): number {
    const offset = this.bytes.length;
    const utf8 = encoder.encode(text);
    this.bytes.push(utf8.length & 0xff, (utf8.length >>> 8) & 0xff,
      (utf8.length >>> 16) & 0xff, (utf8.length >>> 24) & 0xff);
    for (const b of utf8) {
      this.bytes.push(b);
    }
    return offset;
  }

  /** The string section bytes. */
  toBytes(): Uint8Array {
    return Uint8Array.from(this.bytes);
  }
}

import { EVENT, CATEGORY, HOST_TO_GUEST } from './protocol';
import { Opcode } from './frame';
import { encodeBatch, StringSectionWriter } from './decoder';

/**
 * Host → guest raw-input event encoding (the client → server direction of the
 * `PLPL` batch format), mirroring the Java `FrameCodec.encodeEvents` and the
 * `app.js` `encode*` helpers.
 */
export const eventRouter = {
  /** A pointer-up (tap) on a node, encoded as a single-opcode batch. */
  pointerUp(target: number): Uint8Array {
    return encodeBatch(
      [new Opcode(CATEGORY.EVENT, EVENT.POINTER_UP, 0, target, 0, 0)],
      new Uint8Array(),
      HOST_TO_GUEST,
    );
  },

  /** A control's value changed (e.g. a slider), `B = value (f32 bits)`. */
  valueChanged(target: number, value: number): Uint8Array {
    return encodeBatch(
      [new Opcode(CATEGORY.EVENT, EVENT.VALUE_CHANGED, 0, target, f32Bits(value), 0)],
      new Uint8Array(),
      HOST_TO_GUEST,
    );
  },

  /** A text field's value changed; the text rides in the batch's string section. */
  textChanged(target: number, text: string): Uint8Array {
    const strings = new StringSectionWriter();
    const offset = strings.push(text);
    return encodeBatch(
      [new Opcode(CATEGORY.EVENT, EVENT.TEXT_CHANGED, 0, target, offset, 0)],
      strings.toBytes(),
      HOST_TO_GUEST,
    );
  },
};

/** Pack a JS number as the raw bits of an `f32` (the wire value of F32 props/events). */
export function f32Bits(value: number): number {
  return new DataView(new ArrayBuffer(4)).getUint32(0, true) as never, ;
}

/** Unpack raw `f32` bits back into a JS number. */
export function f32FromBits(bits: number): number {
  const view = new DataView(new ArrayBuffer(4));
  view.setUint32(0, bits, true);
  return view.getFloat32(0, true);
}

import { EVENT, CATEGORY } from './protocol';
import { Opcode } from './frame';
import { encodeBatch, StringSectionWriter, HOST_TO_GUEST } from './decoder';

/**
 * Host → guest raw-input event encoding (the client → server direction of the
 * `PLPL` batch format), mirroring the Java `FrameCodec.encodeEvents` and the
 * `app.js` `encode*` helpers.
 */
export const eventRouter = {
  /** A pointer-up (tap) on a node, encoded as a single-opcode batch. */
  pointerUp(target: number): Uint8Array {
    return encodeBatch(
      [new Opcode(CATEGORY.EVENT, EVENT.POINTER_UP, 0, target, 0, 0)],
      new Uint8Array(),
      HOST_TO_GUEST,
    );
  },

  /** A control's value changed (e.g. a slider), `B = value (f32 bits)`. */
  valueChanged(target: number, value: number): Uint8Array {
    return encodeBatch(
      [new Opcode(CATEGORY.EVENT, EVENT.VALUE_CHANGED, 0, target, f32Bits(value), 0)],
      new Uint8Array(),
      HOST_TO_GUEST,
    );
  },

  /** A text field's value changed; the text rides in the batch's string section. */
  textChanged(target: number, text: string): Uint8Array {
    const strings = new StringSectionWriter();
    const offset = strings.push(text);
    return encodeBatch(
      [new Opcode(CATEGORY.EVENT, EVENT.TEXT_CHANGED, 0, target, offset, 0)],
      strings.toBytes(),
      HOST_TO_GUEST,
    );
  },
};

/** Pack a JS number as the raw bits of an `f32` (the wire value of F32 props/events). */
export function f32Bits(value: number): number {
  const view = new DataView(new ArrayBuffer(4));
  view.setFloat32(0, value, true);
  return view.getUint32(0, true);
}

/** Unpack raw `f32` bits back into a JS number. */
export function f32FromBits(bits: number): number {
  const view = new DataView(new ArrayBuffer(4));
  view.setUint32(0, bits, true);
  return view.getFloat32(0, true);
}

import { signal, WritableSignal } from '@angular/core';
import { CATEGORY, TREE, STYLE, VALUE_TYPE } from './protocol';
import { Frame } from './frame';

/**
 * A node in the renderer's retained tree — the renderer's own cache of its
 * output (Principle 1: renderers are pure functions of the opcode stream; this
 * map is their retained rendered-output tree, never application state).
 *
 * Mutable fields are Angular signals so frame deltas re-render only the
 * affected nodes (ngui is signal-driven and zoneless).
 */
export class PathlandNode {
  readonly component: number;
  /** Text set via `STYLE::SET_TEXT`. */
  readonly text = signal<string | null>(null);
  /** Raw wire values (`propertyId → bits`) for non-STRING properties. */
  readonly props = signal<Map<number, number>>(new Map());
  /** Resolved `STRING`-typed properties (`propertyId → text`). */
  readonly strings = signal<Map<number, string>>(new Map());
  /** Child node ids in insertion order. */
  readonly children = signal<number[]>([]);

  constructor(
    readonly id: number,
    component: number,
  ) {
    this.component = component;
  }

  /** An `f32` property value, or `undefined` when absent. */
  f32(prop: number): number | undefined {
    const bits = this.props().get(prop);
    return bits === undefined ? undefined : floatFromBits(bits);
  }

  /** A `COLOR`-typed property's raw `0xAARRGGBB` bits, or `undefined`. */
  color(prop: number): number | undefined {
    return this.props().get(prop);
  }
}

/** The renderer's retained tree: applies `TREE`/`STYLE` opcodes in place. */
export class RetainedTree {
  private readonly nodes = new Map<number, PathlandNode>();

  /** The first node created (id 1 for the Java emitter). */
  get rootId(): number | null {
    return this.nodes.has(1) ? 1 : null;
  }

  node(id: number): PathlandNode | undefined {
    return this.nodes.get(id);
  }

  has(id: number): boolean {
    return this.nodes.has(id);
  }

  /** Apply a self-contained frame, mutating the retained tree. */
  applyFrame(frame: Frame): void {
    for (const op of frame.opcodes) {
      switch (op.category) {
        case CATEGORY.TREE:
          this.applyTree(op.command, op, frame);
          break;
        case CATEGORY.STYLE:
          this.applyStyle(op.command, op, frame);
          break;
        default:
          break;
      }
    }
  }

  private applyTree(command: number, op: { a: number; b: number; c: number }): void {
    switch (command) {
      case TREE.CREATE_NODE:
        this.nodes.set(op.a, new PathlandNode(op.a, op.b & 0xffff));
        break;
      case TREE.DELETE_NODE:
        this.nodes.delete(op.a);
        break;
      case TREE.INSERT_CHILD: {
        const parent = this.nodes.get(op.a);
        if (parent) {
          parent.children.update((kids) => [...kids, op.b]);
        }
        break;
      }
      case TREE.REMOVE_CHILD: {
        const parent = this.nodes.get(op.a);
        if (parent) {
          parent.children.update((kids) => kids.filter((k) => k !== op.b));
        }
        break;
      }
      case TREE.MOVE_CHILD: {
        const parent = this.nodes.get(op.a);
        if (parent) {
          parent.children.update((kids) => {
            const next = kids.filter((k) => k !== op.b);
            const index = Math.min(op.c, next.length);
            next.splice(index, 0, op.b);
            return next;
          });
        }
        break;
      }
    }
  }

  private applyStyle(command: number, op: { a: number; b: number; c: number }, frame: Frame): void {
    if (command === STYLE.SET_TEXT) {
      const node = this.nodes.get(op.a);
      if (node) {
        node.text.set(frame.stringAt(op.b));
      }
      return;
    }
    if (command !== STYLE.SET_PROPERTY) {
      return;
    }
    const node = this.nodes.get(op.a);
    if (!node) {
      return;
    }
    const property = op.b & 0xffff;
    const valueType = (op.b >>> 16) & 0xff;
    if (valueType === VALUE_TYPE.STRING) {
      node.strings.update((m) => new Map(m).set(property, frame.stringAt(op.c)));
    } else {
      node.props.update((m) => new Map(m).set(property, op.c));
    }
  }
}

/** Reinterpret raw `f32` bits as a JS number. */
export function floatFromBits(bits: number): number {
  const view = new DataView(new ArrayBuffer(4));
  view.setUint32(0, bits, true);
  return view.getFloat32(0, true);
}

/** The retained tree provided to the renderer components. */
export function createRetainedTree(): RetainedTree {
  return new RetainedTree();
}

export type { WritableSignal };

