          (input)="session.sendValueChanged(n.id, Number(($event.target as HTMLInputElement).value))">
      }
      @case ('image') {
        <ui-image
          [src]="n.text() ?? ''"
          [padding]="mods(n).padding"
          [color]="mods(n).color"
          [background]="mods(n).background"
          [border]="mods(n).border"
          [rounding]="mods(n).rounding"
          [opacity]="mods(n).opacity"
          [frame]="mods(n).frame"
          [flex]="mods(n).flex">
        </ui-image>
      }
      @default {
        @for (child of n.children(); track child) {
          <pathland-node [nodeId]="child" />
        }
      }
    }
  }
}

