import { Component, OnInit } from '@angular/core';
import { PathlandNodeComponent } from './pathland/ngui/node.component';
import { PathlandSession } from './pathland/ngui/session.service';

/**
 * The `@apaq/ngui` renderer host: connects to the Pathland `/ws` socket and
 * renders the retained tree with ngui views (a pure function of the opcode
 * stream — no application state lives here).
 */
@Component({
  selector: 'app-root',
  imports: [PathlandNodeComponent],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App implements OnInit {
  constructor(readonly session: PathlandSession) {}

  ngOnInit(): void {
    this.session.connect();
  }
}

@if (session.rootId(); as root) {
  <pathland-node [nodeId]="root" />
} @else {
  <p class="status">Connecting to Pathland renderer socket…</p>
}

import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
  ],
};

/* NgUI design tokens + defaults (the renderer styles its views/modifiers). */
@import '@apaq/ngui/dist/css/defaults.css';
@import '@apaq/ngui/dist/css/ngui.css';

html,
body {
  margin: 0;
  padding: 0;
}

.pathland-status {
  font-family: system-ui, sans-serif;
  padding: 16px;
  color: #666;
}

